import csv
import io

def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
        records = [row for row in reader if row]
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])
    columns.extend([""] * (width - len(columns)))

    while columns and not columns[-1] and all(
        len(row) < len(columns) or not row[len(columns) - 1] for row in rows
    ):
        columns.pop()

    width = len(columns)
    used = set(name for name in columns if name)
    for i, name in enumerate(columns):
        if not name:
            base = "Column " + str(i + 1)
            candidate = base
            suffix = 2
            while candidate in used:
                candidate = base + "_" + str(suffix)
                suffix += 1
            columns[i] = candidate
            used.add(candidate)

    normalized = [(row[:width] + [""] * max(0, width - len(row))) for row in rows]
    return {"columns": columns, "rows": normalized}
